"import fs from 'fs';
import path from 'path';

const [filePath, targetContentFile, replacementContentFile] = process.argv.slice(2);

try {
  const fileContent = fs.readFileSync(filePath, 'utf8');
  const targetContent = fs.readFileSync(targetContentFile, 'utf8');
  const replacementContent = fs.readFileSync(replacementContentFile, 'utf8');

  if (!fileContent.includes(targetContent)) {
    console.error('Error: Target content not found in file ' + filePath);
    process.exit(1);
  }

  const newContent = fileContent.replace(targetContent, replacementContent);
  fs.writeFileSync(filePath, newContent, 'utf8');
  console.log('Successfully patched ' + filePath);
} catch (err) {
  console.error('Error patching file:', err);
  process.exit(1);
}
